import datetime
class Solution:
    def fridayPurchases(self, purchases):
        totals = {}
        for u, d, amt in purchases:
            totals[d] = totals.get(d, 0) + amt
        res = []
        for d, amt in totals.items():
            if datetime.date(*map(int, d.split('-'))).weekday() == 4:
                day = int(d[8:10])
                res.append((day // 7 + 1, d, amt))
        return sorted(res)

