#include <bits/stdc++.h>
using namespace std;
class Solution {
public:
    vector<array<long long,3>> fridayPurchases(vector<vector<int>>& purchases) {
        map<int,long long> totals;
        for (auto& p : purchases)
            totals[p[1]] += p[2];
        vector<array<long long,3>> res;
        for (auto& [day, amt] : totals) {
            int dow = (day - 1 + 2) % 7;
            if (dow == 4)
                res.push_back({(long long)(day / 7 + 1), (long long)day, amt});
        }
        return res;
    }
};

