import java.util.*;
class Solution {
    public List<long[]> fridayPurchases(int[][] purchases) {
        TreeMap<Integer, Long> totals = new TreeMap<>();
        for (int[] p : purchases)
            totals.merge(p[1], (long) p[2], Long::sum);
        List<long[]> res = new ArrayList<>();
        for (Map.Entry<Integer, Long> e : totals.entrySet()) {
            int day = e.getKey();
            if ((day - 1 + 2) % 7 == 4)
                res.add(new long[]{day / 7 + 1, day, e.getValue()});
        }
        return res;
    }
}

c.javascript:
var fridayPurchases = function(purchases) {
    const totals = new Map();
    for (const [u, d, amt] of purchases)
        totals.set(d, (totals.get(d) || 0) + amt);
    const res = [];
    for (const [d, amt] of totals) {
        const day = parseInt(d.slice(8, 10));
        if (new Date(d + 'T00:00:00Z').getUTCDay() === 5)
            res.push([Math.floor(day / 7) + 1, d, amt]);
    }
    return res.sort((a, b) => a[0] - b[0]);
};

